const text = v => !v ? "" : (v.title||v.rich_text||[]).map(t=>t.plain_text).join("");
let war = true; // design: an unreadable or missing War Mode flag is treated as ON (FIRE still interrupts)
for (const it of $('Notion System Flags').all()) {
  const p = it.json.properties || {};
  let title = "";
  for (const k in p) if (p[k] && p[k].type === "title") title = text(p[k]);
  if (/^\s*war mode\s*$/i.test(title)) war = p["Value"]?.checkbox === true;
}
const SEV = ["FIRE","IMPORTANT","ROUTINE","AWARENESS"];
const OWN = ["Conductor","Estimator","Support","Marketer","Shield/Ops","Researcher"];
const body = $('Inbound Webhook').first().json.body || {};
const hay = String(body.subject||"") + " " + String(body.text||"");
let r;
let llmFailed = false;
try {
  const rawText = $json.content?.[0]?.text;
  if (!rawText) { llmFailed = true; throw new Error("empty or error response"); }
  let raw = rawText.trim().replace(/^```(?:json)?/i,"").replace(/```$/,"").trim();
  const m = raw.match(/\{[\s\S]*\}/);
  const o = JSON.parse(m ? m[0] : raw);
  if (!SEV.includes(o.severity) || !OWN.includes(o.owner)) throw new Error("bad enum");
  r = { severity:o.severity, owner:o.owner, reason:String(o.reason||""), needs_human:o.needs_human===true, summary:String(o.summary||"") };
} catch (e) {
  r = { severity:"IMPORTANT", owner:"Conductor", reason: llmFailed ? "Router LLM call failed; defaulting to human review." : "Router output could not be parsed; defaulting to human review.", needs_human:true, summary:"" };
}
r.llm_failed = llmFailed;
// Deterministic keyword floor: LLM output alone may never go below IMPORTANT for risky words.
r.keyword_floor = false;
if (/\b(injur\w*|fire|gas|police|lawsuit|sue|sued|attorney|lawyer|chargeback|refund\w*)\b/i.test(hay) && (r.severity === "ROUTINE" || r.severity === "AWARENESS")) {
  r.severity = "IMPORTANT"; r.needs_human = true; r.keyword_floor = true;
  r.reason = (r.reason ? r.reason + " " : "") + "[keyword floor: raised to IMPORTANT]";
}
r.queued_for_brief = false;
if (war && r.severity !== "FIRE") { r.needs_human = false; r.queued_for_brief = true; }
r.war_mode = war;
return [{ json: { routing: r } }];
